SELECT 'gongkao', '环比', 'kp-xingce-data-term-qoq', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "环比"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“环”指紧紧相邻。与上一个紧紧相连的统计周期相比。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "与上一个紧紧相邻的周期作比较，特征词通常包含“环比增长”、“与上月相比”、“与上季度相比”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "环比增长率 = \\frac{本期量 - 上一相邻周期量}{上一相邻周期量}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到'环比'二字] --> B[年份不变, 周期减1]\nB --> C{是否跨年?}\nC -- 是(如1月) --> D[年份减1, 月份变12月]\nC -- 否 --> E[正常找上个月/上个季度的基期量]\nE --> F[套用公式进行计算]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2024年1月，我国汽车销量为 200 万辆，环比下降 5%。求2023年12月的汽车销量？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "识别：题干问的是2024年1月的“环比”，且给出现期量和环比降幅。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "跨年推导：1月的上一个月是去年的12月，所以基期是2023年12月。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：基期量 = 现期量 / (1 - 降幅) = 200 / (1 - 5%) = 200 / 0.95。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "截位直除：200 ÷ 0.95 ≈ 210.5 万辆。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "⚠️ 年初跨年陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "最容易错的就是 1月 的环比！2024年1月的环比基期，不是2023年1月（那是同比），而是 2023年12月！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "刷题时遇到“1月”和“第一季度”的数据，务必在草稿纸上画个圈警告自己。专门找混合“同比”与“环比”的连环倒推题练手。"}]}]}$$ AS jsonb), NULL, '环比的核心考点与速算。', category_node.id, CAST('["资料分析", "环比"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_term_qoq", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
